using System;using System.IO;using System.Linq;using System.Net;using System.Text;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using DualSteam;using DualSteam.UI;
public partial class App {
 bool startupAuthorized,serviceChecking;string startupEnvelope;string serviceDecision="checking",serviceMessage="Checking startup availability…";ServiceDocument startupPolicy;
 static string FetchServicePolicy(){var addresses=new[]{"https://api.github.com/repos/w-rakeeb/dual-steam/contents/service-policy.json?ref=main&startup="+Guid.NewGuid().ToString("N"),ServicePolicy.Address+"?startup="+Guid.NewGuid().ToString("N")};var pending=addresses.Select(address=>Task.Run(()=>{try{string value=ReadServicePolicy(address);ServicePolicy.Verify(value);return value;}catch(Exception ex){Engine.Log("Startup route: "+ex.Message);return null;}})).ToList();while(pending.Count>0){var done=Task.WhenAny(pending).GetAwaiter().GetResult();pending.Remove(done);if(!String.IsNullOrEmpty(done.Result))return done.Result;}throw new IOException("Neither GitHub startup route could be verified. Check your connection and retry.");}
 static string ReadServicePolicy(string address){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create(address);request.UserAgent="DualSteam/"+UpdateService.CurrentVersion;request.Accept="application/vnd.github.raw+json";request.Timeout=30000;request.ReadWriteTimeout=30000;request.AllowAutoRedirect=false;request.CachePolicy=new System.Net.Cache.RequestCachePolicy(System.Net.Cache.RequestCacheLevel.NoCacheNoStore);using(var response=(HttpWebResponse)request.GetResponse())using(var input=response.GetResponseStream())using(var output=new MemoryStream()){var buffer=new byte[4096];int read;while((read=input.Read(buffer,0,buffer.Length))>0){if(output.Length+read>65536)throw new IOException("The service response is too large.");output.Write(buffer,0,read);}return new UTF8Encoding(false,true).GetString(output.ToArray());}}
 bool ServiceReady(){if(render||startupAuthorized)return true;ShowManager();ShowPage("Service");return false;}
 async void AuthorizeStartup(){
  if(serviceChecking||startupAuthorized)return;serviceChecking=true;serviceDecision="checking";serviceMessage="Checking startup availability…";ShowPage("Service");
  try{RuntimeAuthorization.BeginStartup(Engine.Home);var fetch=Task.Run(()=>FetchServicePolicy());if(await Task.WhenAny(fetch,Task.Delay(45000))!=fetch)throw new IOException("The startup check timed out. Please retry.");string envelope=await fetch;startupPolicy=ServicePolicy.Verify(envelope);serviceDecision=ServicePolicy.Decision(startupPolicy,UpdateService.ParseVersion(UpdateService.CurrentVersion));serviceMessage=startupPolicy.Announcement;
   if(serviceDecision=="allowed"){RuntimeAuthorization.Authorize(Engine.Home,envelope);startupEnvelope=envelope;startupAuthorized=true;nextUpdate=DateTime.UtcNow.AddHours(6);Preferences.Current.KeepSecondRunning=false;Preferences.Save();ShowPage("Profiles");try{if(AccountAppearance.NeedsDefaults)await Task.Run(()=>AccountAppearance.EnsureDefaults());}catch(Exception ex){Engine.Log("Account appearance: "+ex.Message);toast.Show("Sign-in hiding was not applied. Use Settings → General → Windows account appearance to retry.");}if(exitRequested)return;if(options.Contains("--second"))LaunchSecond();if(startupPolicy.Release!=null)updateFeedback.Complete(UpdateService.ParseVersion(UpdateService.CurrentVersion),ServicePolicy.Version(startupPolicy.RequiredVersion));}
   else{if(serviceDecision=="update"&&startupPolicy.Release!=null){var r=startupPolicy.Release;availableRelease=new ReleaseInfo{Tag=r.Tag,Version=ServicePolicy.Version(startupPolicy.RequiredVersion),Page="https://github.com/"+UpdateService.Repository+"/releases/tag/"+r.Tag,Download=r.Url,Sha256=r.Sha256,Size=r.Size};}ShowManager();ShowPage("Service");}
  }catch(Exception ex){startupAuthorized=false;try{RuntimeAuthorization.BeginStartup(Engine.Home);}catch{}serviceDecision="unavailable";serviceMessage="The startup service check could not be verified. Internet access is required when starting Dual Steam. "+ex.Message;Engine.Log("Startup policy: "+ex.Message);ShowManager();ShowPage("Service");}finally{serviceChecking=false;if(page=="Service")ShowPage("Service");}
 }
 FrameworkElement ServicePage(){var body=Stack();string title=serviceDecision=="paused"?"Service temporarily paused":serviceDecision=="shutdown"?"Service closed":serviceDecision=="update"?"Update required":serviceDecision=="unavailable"?"Service check unavailable":"Checking service availability";Heading(title,"This check applies to this startup. Main Steam remains independent.",body);body.Children.Add(Group(Text(serviceMessage??"",14,"text.primary",true)));if(startupPolicy!=null)body.Children.Add(Text("Announcement updated: "+DateTime.Parse(startupPolicy.PublishedUtc,System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.RoundtripKind).ToLocalTime().ToString("G"),12,"text.muted"));
  if(serviceChecking)body.Children.Add(new ProgressBar{Height=4,IsIndeterminate=true,Margin=new Thickness(0,0,0,16)});
  if(serviceDecision=="update"){body.Children.Add(Text("Install version "+startupPolicy.RequiredVersion+" before using Second Steam. Your configured profiles and game libraries are preserved.",13,"text.secondary"));if(availableRelease!=null){body.Children.Add(ActionButton("Install required update",InstallUpdate,true));body.Children.Add(ActionButton("Download ZIP instead",()=>OpenPath(availableRelease.Download)));body.Children.Add(Text("If installation fails, fully exit the manager and extract the ZIP over this app folder, replacing matching files. Keep Data and Profiles.",13,"text.secondary"));}}
  if(!serviceChecking)body.Children.Add(ActionButton("Retry startup check",AuthorizeStartup,serviceDecision!="update"));body.Children.Add(ActionButton("View releases and announcements",()=>OpenPath("https://github.com/"+UpdateService.Repository+"/releases")));body.Children.Add(Text("The publisher can require updates, pause or close the service at the next full startup. An already authorized open session keeps working. Closing to the tray keeps that session open; fully exiting ends it. Settings and setup removal stay available.",13,"text.secondary"));return body;}
}
